def p(id, label, style, diet, about, voice, pitch, speed, cred, follow, likes=(), dislikes=()):
    return {"id": M + id, "label": label, "style": style, "diet": diet, "about": about, "address": "Humano",
            "likes": [M + x for x in likes], "dislikes": [M + x for x in dislikes], "wants": [], "drops": [],
            "voice": voice, "pitch": pitch, "speed": speed, "credulity": cred, "follow": follow}


